def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[background] * w for _ in range(h)]

    # Retain cells that belong to a solid 2x2 patch of a non-background color;
    # these patches represent the rectangular objects, while isolated marks
    # and holes are noise.
    for r in range(h - 1):
        for c in range(w - 1):
            color = grid[r][c]
            if color != background and all(
                grid[y][x] == color
                for y, x in ((r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1))
            ):
                for y, x in ((r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)):
                    out[y][x] = color
    return out
